WITH base AS (SELECT *, LOWER(email) AS email_lower, COALESCE(level, 'OTHER') AS level_clean FROM employees WHERE hire_date > DATE '2023-07-24' AND job_title IS NOT DISTINCT FROM 'Director') SELECT DATE_TRUNC('MONTH', hire_date) AS activity_month, CASE WHEN salary >= 125000 THEN 'PREMIUM' ELSE 'STANDARD' END AS salary_tier, DATE_TRUNC('YEAR', hire_date) AS year_start, SUM(CASE WHEN level = 'L4' THEN salary ELSE 0 END) AS l4_salary, SIZE(COLLECT_SET(level)) AS num_levels, GROUPING(DATE_TRUNC('MONTH', hire_date)) AS grouping_level FROM base GROUP BY GROUPING SETS ((DATE_TRUNC('MONTH', hire_date), CASE WHEN salary >= 125000 THEN 'PREMIUM' ELSE 'STANDARD' END, DATE_TRUNC('YEAR', hire_date)), (DATE_TRUNC('MONTH', hire_date), CASE WHEN salary >= 125000 THEN 'PREMIUM' ELSE 'STANDARD' END), (DATE_TRUNC('MONTH', hire_date)))
